import math

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        tree = [0] * (2 * n)

        def update(i, x):
            i += n
            while i > 0:
                tree[i] += x
                i -= i & -i

        def sum_range(l, r):
            s = 0
            r += 1
            while l < r:
                if l & 1:
                    s += tree[l]
                    l += 1
                l = l // 2
                if r % 2:
                    s += tree[r]
                    r -= 1
                r = r // 2
            return s

        def sort():
            for i in range(1, n + 1):
                update(i, -a[i - 1])
                for j in range(i + (i & -i), n + 1, i):
                    a[j - i] = max(a[j - i], sum_range(j, n) - sum_range(j - i, n))
                update(i, a[i - 1])

        for m in range(int(math.log2(n)) + 1):
            for i in range(1 << m, n + 1, 1 << m):
                update(i, -a[i - 1])
                for j in range(i + (i & -i), n + 1, i):
                    a[j - i] = max(a[j - i], sum_range(j, n) - sum_range(j - i, n))
                update(i, a[i - 1])

        if all(i <= j for i, j in zip(a, a[1:])):
