def solve():
    input_lines = sys.stdin.readlines()
    tc = int(input_lines[0].strip())
    input_lines = input_lines[1:]
    for _ in range(tc):
        n, m = map(int, input_lines[_*2].split())
        p = list(map(int, input_lines[_*2+1].split()))
        res = [-1] * n
        dq = deque(range(1, n+1))
        for i in range(m):
            if p[i] in dq:
                dq.remove(p[i])
                dq.appendleft(p[i])
            else:
                dq.appendleft(p[i])
                if len(dq) > n:
                    dq.pop()
                    for j in range(n):
                        if dq[j] == j+1:
                            res[j] = i+1
        print(*res)

