import heapq

def solve():
    n, m = map(int, sys.stdin.readline().split())
    pq = [(0, 0, 0)]
    visited = set((0, 0))
    while pq:
        d, x, y = heapq.heappop(pq)
        if (x, y) == (n - 1, m - 1):
            return -d
        for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                visited.add((nx, ny))
                heapq.heappush(pq, (d + nx * m + ny + 1, nx, ny))
    return -1
